for region in ['fluid','solid']:
    cp=subprocess.run(['checkMesh','-region',region,'-allTopology','-allGeometry'],text=True,capture_output=True)
    check_reports[region]=cp.stdout+cp.stderr
    print(f'===== {region} =====')
    lines=check_reports[region].splitlines()
    print('\n'.join(lines[-42:]))
